INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (1, 1001, 0, 0, "ねぇねぇ、騎士クン\n手伝ってあげようよ～", 2, 0, 0, "春咲 ひより", "ヒヨリでっす♪\n元気いっぱいがんばるよ♪", 1, 1.4, 0, 1, "お！\nあそこに困ってそうな人発見！");
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (1, 1002, 0, 0, "わ、わたし、\nなに言ってるんだろ\nあはは…", 2, 0, 0, "草野 優衣", "みんなみたいに\nわたしも強くならなきゃ", 1, 1.4, 0, 1, "大切な人を\n守れるようになりたい…って");
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (1, 1003, 0, 0, "少しは磨かれると思いますよ。", 2, 0, 0, "士条 怜", "フェンシングを始めてみては？", 1, 1.4, 0, 1, "キミに必要な集中力と感性が");
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (1, 1004, 0, 0, "みそぎはねぇ、\nかくれんぼやりたい！", 2, 0, 0, "穂高 みそぎ", "ねぇ、にいちゃん！", 1, 1.5, 0, 1, "今日はなにして遊ぶ？");
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (1, 1006, 0, 0, "私といっしょに…\nいかない？", 2, 0, 0, "風宮 あかり", "風宮あかりです", 1, 1.4, 0, 1, "ねぇ…");
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (1, 1007, 0, 0, "食べ物の恨みは怖いのー", 2, 0, 0, "出雲 宮子", "出雲宮子なのー", 1, 1.5, 0, 1, "プリンたべたいのー");
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (1, 1008, 0, 0, "いいよ。\n見られることは運命さ…", 2, 0, 0, "虹村 雪", "ボクは虹村雪。", 1, 1.4, 0, 1, "キミもボクの美貌に\n吸い寄せられたんだね。");
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (1, 1009, 0, 0, "人呼んで「疾風の冥姫」!!", 2, 0, 0, "柊杏奈", "フッ…聞いて後悔するがいい！", 1, 1.4, 0, 1, "我が真名は\nアンネローゼ・フォン・シュテッヒパルム！");
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (1, 1010, 0, 0, "ほんまおおきにやわ～♪", 2, 0, 0, "姫宮 真歩", "マホマホ王国のプリンセス、\nまほ姫どす", 1, 1.5, 0, 1, "うさぎさん、\n運命の王子はんに巡りあわせてくれて");
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (1, 1011, 0, 0, "ここで会ったが\n100年目～！", 2, 0, 0, "衣之咲 璃乃", "衣之咲璃乃です！", 1, 1.4, 0, 1, "生き別れたお兄ちゃんを探して\n三千世界！");
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (1, 1012, 0, 0, "…って、お願い！\n誰にも言わないでおいて～！", 2, 0, 0, "柏崎 初音", "私はハツネ、\n結構強いんだよ。\nきらーん☆", 1, 1.4, 0, 1, "ち、超能力って…\n何のことかな～？");
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (1, 1016, 0, 0, "ヒデサイまぢ\nGF（グッドフィーリング）～♪", 2, 0, 0, "美波 鈴奈", "ちょす！\n美波鈴奈だよ～♪", 1, 1.4, 0, 1, "一応カリスマ読モJKやってまっす！");
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (1, 1017, 0, 0, "でも、沖縄もとってもいいとこさー", 2, 0, 0, "喜屋武 香織", "はいたーい。\n喜屋武香織さー。", 1, 1.4, 0, 1, "東京は遊園地みたいなところさー");
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (1, 1018, 0, 0, "イオちゃんって呼んでね。", 2, 0, 0, "支倉 伊緒", "支倉伊緒です。", 1, 1.4, 0, 1, "先生って呼ばれるのは\nくすぐったいから");
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (1, 1020, 0, 0, "ミミをおいてかないでぇ～", 2, 0, 0, "茜 ミミ", "ふえ…？\nミミ、むずかしいこと\nよくわかんない…", 1, 1.5, 0, 1, "あ！/\お兄ちゃ～ん\nまってよ～");
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (1, 1021, 0, 0, "ふぇぇぇぇぇん……", 2, 0, 0, "栗林 くるみ", "あ…あの…えっと…\n栗…林…くるみ…です……", 1, 1.5, 0, 1, "あの……\nふぇ……");
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (1, 1022, 0, 0, "なんてありがとうございます！", 2, 0, 0, "風宮 より", "風宮よりです。\nあああああ！", 1, 1.4, 0, 1, "こんな私に貴重な時間を\n割いていただき、");
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (1, 1023, 0, 0, "私こっち行きたいー\nね、早く早くー", 2, 0, 0, "北条 綾音", "私、アヤネ！\nぷうきちと一緒についてってあげるね！", 1, 1.5, 0, 1, "おにいちゃんどこいくの？\nえ？");
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (1, 1025, 0, 0, "これて何か違う…\nあああすみません！", 2, 0, 0, "天野 すずめ", "わっ…わっ…私、\n天野すずめといいます！", 1, 1.4, 0, 1, "ふ、不束者ですが\nどうぞ末永く…って、");
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (1, 1027, 0, 0, "離しませんわ………\n絶対に…!!", 2, 0, 0, "倉石 恵理子", "……クスクス…私は\n…倉石恵理子……", 1, 1.4, 0, 1, "あなたは…運命の……\n伴侶……");
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (1, 1028, 0, 0, "…そうでしょ？？", 2, 0, 0, "佐々木 咲恋", "佐々木咲恋よ。\nねえ、世の中に無駄なことが\n多すぎると思わない？", 1, 1.4, 0, 1, "その無駄を省くことができれば、\nもっと余裕のある暮らしができるっ！");
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (1, 1029, 0, 0, "あはは、\n私もまだまだだなぁ～", 2, 0, 0, "桜井 望", "桜井望だよ！\nよろしくねっ", 1, 1.4, 0, 1, "ぇっと…\nキミ、私のこと知らないの?!");
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (1, 1030, 0, 0, "ショーグン、\nワタシと一緒に天下統一デース！", 2, 0, 0, "ニノン・ジュベール", "デケデケデンっ！", 1, 1.4, 0, 1, "初めまして、\n私はニノン・ジュベール申すデス！");
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (1, 1031, 0, 0, "おかしいですね……", 2, 0, 0, "上喜 しのぶ", "上喜しのぶです。\n手元のドクロが父です。", 1, 1.4, 0, 1, "でもって私の隣にいるのが……\nえ、見えない？");
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (1, 1033, 0, 0, "そう、\nオラのボケに突っ込める相方が…！", 2, 0, 0, "野戸まひる", "目指すはビッグな\nお笑い芸人だっぺ！", 1, 1.5, 0, 1, "けんども\nそれには足りないモンが…");
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (1, 1034, 0, 0, "ちょ\nちょっと一杯飲んできます…！", 2, 0, 0, "綾瀬 ゆかり", "あの…私…綾瀬ゆかりです…\nあの…ごめんなさい！", 1, 1.4, 0, 1, "ちょっと緊張しちゃって…");
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (1, 1036, 0, 0, "これ以上お話しすることは…\nないです！", 2, 0, 0, "氷川 鏡華", "氷川鏡華…です", 1, 1.5, 0, 1, "知らない人とは話しちゃいけないので");
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (1, 1038, 0, 0, "私体が弱いから、\n30分に一度休憩しないと\nいけないんです。", 2, 0, 0, "柏崎 栞", "柏崎…栞です。", 1, 1.4, 0, 1, "……あ、アラーム。");
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (1, 1040, 0, 0, "野に咲く花が、\n唯一の話相手です。", 2, 0, 0, "双葉 碧", "ふ、双葉碧です。", 1, 1.4, 0, 1, "私、一人も友達がいなくて……");
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (1, 1042, 0, 0, "そう思っています。", 2, 0, 0, "三角 千歌", "三角千歌です。", 1, 1.4, 0, 1, "私の歌声で、\n皆さんが幸せになってくれたらいいなって…");
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (1, 1043, 0, 0, "う、疑ってすまなかったな…", 2, 0, 0, "安芸 真琴", "安芸真琴だ。", 1, 1.4, 0, 1, "あぁ？\nお前のそいつの仲間か？");
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (1, 1044, 0, 0, "わらわの偉大な力に\nひれ伏すがいい！\nはっはっは！", 2, 0, 0, "イリヤ・オーンスタイン", "わらわこそは夜を総べる者！", 1, 1.4, 0, 1, "生けとし生ける全ての者よ！");
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (1, 1045, 0, 0, "ｌク、クウカに何かご用ですか!?", 2, 0, 0, "遠見 空花", "そこで騎士は妖精を乱暴に……", 1, 1.4, 0, 1, "ぐふふふふ……はっ！");
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (1, 1046, 0, 0, "う～ん…\n猫ってホントに最高にゃ～♪", 2, 0, 0, "宮坂たまき", "宮坂たまきにゃ♪\n猫はいいにゃよ？", 1, 1.4, 0, 1, "自由気ままで♪\n寝て遊んで、食べてケンカして…");
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (1, 1048, 0, 0, "…と思ったら\nバイトの時間だ！\nまたあとでね！", 2, 0, 0, "大神 美冬", "大神美冬よ！", 1, 1.4, 0, 1, "それでは早速クエストに…");
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (1, 1049, 0, 0, "お姉ちゃんがぜ～んぶ\nやってあげるからね！", 2, 0, 0, "星野静流", "星野静流だよ！", 1, 1.4, 0, 1, "クエストもバトルも\n掃除も洗濯も");
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (1, 1050, 0, 0, "学校では誰もが憧れる\nアイドル的な存在ってやつよ♪", 2, 0, 0, "玉泉美咲", "アタシは玉泉美咲。", 1, 1.5, 0, 1, "見ての通りの\nセクシー美少女で");
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (1, 1052, 0, 0, "？？？？", 2, 0, 0, "リマ", "？？？", 1, 1.4, 0, 1, "？？？？");
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (1, 1053, 0, 0, "そ、そこまでいうなら\nもらってやる", 2, 0, 0, "モニカ・ヴァイスヴィント", "モニカ・ヴァイスヴィントだ。", 1, 1.5, 0, 1, "菓子でつろうなどと\n稚拙な策を……");
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (1, 1058, 0, 0, "そ、そこまでいうなら\nもらってやる", 2, 0, 0, "ペコリーヌ", "モニカ・ヴァイスヴィントだ。", 1, 1.5, 0, 1, "菓子でつろうなどと\n稚拙な策を……");
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (1, 1059, 0, 0, "そ、そこまでいうなら\nもらってやる", 2, 0, 0, "コッコロ", "モニカ・ヴァイスヴィントだ。", 1, 1.5, 0, 1, "菓子でつろうなどと\n稚拙な策を……");
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (1, 1060, 0, 0, "そ、そこまでいうなら\nもらってやる", 2, 0, 0, "キャル", "モニカ・ヴァイスヴィントだ。", 1, 1.5, 0, 1, "菓子でつろうなどと\n稚拙な策を……");
